import 'package:flutter/material.dart';import '../services/global_tours_service.dart';
class FinanceScreen extends StatelessWidget{const FinanceScreen({super.key,required this.user});final Map<String,dynamic> user;@override Widget build(BuildContext c)=>FutureBuilder(future:GlobalToursService().rawList('payments','${user['tenantId']??''}'),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final r=s.data as List<Map<String,dynamic>>;final total=r.fold<double>(0,(x,a)=>x+(a['amount'] is num?(a['amount'] as num).toDouble():0));return ListView(padding:const EdgeInsets.all(16),children:[Text('Finance & Payments',style:Theme.of(c).textTheme.headlineSmall),Card(child:ListTile(title:const Text('Recorded payments'),trailing:Text('${r.length}'))),Card(child:ListTile(title:const Text('Payment value'),trailing:Text('${user['currency']??'KES'} ${total.toStringAsFixed(2)}'))),...r.map((x)=>Card(child:ListTile(title:Text('${x['reference']??x['provider']??'Payment'}'),subtitle:Text('${x['status']??'unknown'} • ${x['method']??x['paymentMethod']??''}'),trailing:Text('${x['amount']??0}'))))]);});}}
